    engineeringData: { blockDesign: "Cast Iron block with an aluminum cylinder head. The M43 is a massive evolutionary step over the M40. It retains the indestructible iron block but features a timing chain and a completely redesigned valvetrain, solving the major flaws of its predecessor.", crankshaft: "Cast Iron, supported by 5 main bearings. Exceptionally smooth and robust.", pistonSpeed: "15.1 m/s @ 6000 RPM.", alternator: "80A or 105A Bosch (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy.", wristPinDiameter: "22 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M8.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Wedge-shaped combustion chamber.", intakePortFlow: "8-valve SOHC design. While highly restrictive for top-end power, it utilizes a dual-length intake manifold (DISA) to optimize low-end torque.", valveSizes: "Intake: 42.0 mm / Exhaust: 36.0 mm.", valveStemDiameter: "7.0 mm.", camshaftDuration: "Mild duration, optimized entirely for low-end drivability.", lifterType: "Hydraulic bucket tappets with ROLLER rocker arms (Curing the fatal M40 camshaft wear).", specialFeature: "DISA Valve (Dual Resonance Intake System). Alters the length of the intake runners dynamically based on RPM to broaden the torque curve." }, oilAndCooling: { oilSquirters: "No dedicated under-piston cooling jets.", oilPumpType: "Rotor-type pump driven directly by the crankshaft.", thermostatOpening: "95°C Mechanical thermostat (Runs hotter than M40 for better emissions/efficiency).", oilCooler: "None." }, fuelSystem: { systemType: "Bosch Motronic 1.7.1.", maxPressure: "3.0 Bar (Fuel Rail).", injectors: "4x Bosch EV1 Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "250 Nm (Limited by natural aspiration).", maxSafePowerStock: "160 hp (Requires extreme head porting and cams, terrible value for money).", maxSafeRPM: "6200 RPM (Governed by Motronic).", weakestLink: "DISA Valve Flap, Plastic Cooling Flanges, Vacuum Hoses, 8-Valve Head Design." }, electrical: { coils: "Single dual-fire ignition coil pack module (wasted spark system).", ecu: "Bosch Motronic M1.7.1." } },
    recommendedParts: { description: "Crucial maintenance parts to keep the highly reliable M43 engine running smoothly.", parts: [ { category: "DISA Valve Rebuild Kit", brand: "X8R / Aftermarket", note: "CRITICAL: Fixes rattling and prevents engine ingestion." }, { category: "Oil Filter Housing Gasket", brand: "Elring", note: "Cures the most common major oil leak on the M43 block." }, { category: "Rear Coolant Flange", brand: "Genuine BMW", note: "Plastic connector at the back of the head. Replace proactively before it snaps." }, { category: "Vacuum Hose Kit", brand: "Silicone Aftermarket", note: "Replace all old rotting rubber hoses to cure rough idling." }, { category: "Water Pump", brand: "Saleri / Hepu", note: "Replace proactively every 100k km to prevent overheating." }, { category: "Ignition Coil Pack", brand: "Bosch", note: "Replace if experiencing misfires during wet weather." }, { category: "Valve Cover Gasket", brand: "Elring", note: "Prone to leaking oil onto the exhaust manifold." }, { category: "Spark Plugs", brand: "NGK BKR6EK", note: "Dual-ground copper plugs; replace every 30k km." } ] },
