      oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 5W-40 or 10W-40.", parts: ["4.0L 5W-40", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "55 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "40,000 km", timeLimit: "4 years", task: "Fuel Filter", details: "Replace the inline metal fuel filter.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "25 EUR" } ],
      ignitionAndEngine: [ { interval: "80,000 km", timeLimit: "Unlimited", task: "DISA Valve Inspection", details: "Remove the DISA valve from the intake and check for flap play. Rebuild if loose.", parts: ["Rebuild Kit"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "50 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Vacuum System Overhaul", details: "Replace the PCV hose, intake boot, and all small vacuum lines to ensure a smooth idle.", parts: ["Vacuum Hose Kit"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Spark Plugs", details: "Replace standard copper spark plugs.", parts: ["4x NGK Plugs"], importance: "High", laborDifficulty: "Easy", estimatedCost: "30 EUR" }, { interval: "80,000 km", timeLimit: "Unlimited", task: "Valve Cover Gasket", details: "Replace the rubber gasket to stop oil leaking down the engine block.", parts: ["VCG Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "35 EUR" } ],
      preventiveAndSuspension: [ { interval: "100,000 km", timeLimit: "Unlimited", task: "Oil Filter Housing Gasket (OFHG)", details: "Replace the rubber profile gasket behind the oil filter housing to cure the massive oil leak.", parts: ["OFHG Gasket"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "15 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "Control Arm Bushings", details: "Replace the front thrust arm bushings to cure the infamous E-Series 80 km/h steering shimmy.", parts: ["Lemförder Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" } ],
