    engineeringData: { blockDesign: "Cast Iron block with an aluminum cylinder head. The core engine is the highly reliable M43. The 518g (g for Erdgas/Natural Gas) was a rare, eco-focused variant primarily built as an E34 Touring.", crankshaft: "Cast Iron, supported by 5 main bearings. Exceptionally smooth and robust.", pistonSpeed: "15.1 m/s @ 6000 RPM.", alternator: "80A or 105A Bosch (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy.", wristPinDiameter: "22 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M8.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Wedge-shaped combustion chamber.", intakePortFlow: "8-valve SOHC design. Features a modified intake manifold to accommodate the secondary CNG gas injectors.", valveSizes: "Intake: 42.0 mm / Exhaust: 36.0 mm.", valveStemDiameter: "7.0 mm.", camshaftDuration: "Mild duration, optimized entirely for low-end drivability.", lifterType: "Hydraulic bucket tappets with roller rocker arms.", specialFeature: "Bivalent Architecture. The engine starts on petrol and automatically switches to CNG when the coolant reaches a specific temperature and pressure is sufficient." }, oilAndCooling: { oilSquirters: "No dedicated under-piston cooling jets.", oilPumpType: "Rotor-type pump driven directly by the crankshaft.", thermostatOpening: "95°C Mechanical thermostat.", oilCooler: "None." }, fuelSystem: { systemType: "Bosch Motronic 1.7.1 (Petrol) + Integrated CNG Regulator.", maxPressure: "3.0 Bar (Petrol) / 200 Bar (CNG Tank Storage).", injectors: "4x Bosch EV1 Solenoid Injectors (Petrol) + 4x CNG Injectors." }, tuningLimits: { maxSafeTorqueStock: "250 Nm", maxSafePowerStock: "160 hp", maxSafeRPM: "6200 RPM", weakestLink: "Obsolete CNG Hardware, Expiring Gas Tanks, Massive Vehicle Weight." }, electrical: { coils: "Single dual-fire ignition coil pack module.", ecu: "Bosch Motronic M1.7.1 + CNG Module." } },
    recommendedParts: { description: "Crucial maintenance parts for the M43 core engine.", parts: [ { category: "CNG Regulator / Filter", brand: "OEM or Specialist", note: "CRITICAL: Highly specialized part; required to keep the gas system safe." }, { category: "DISA Valve Rebuild Kit", brand: "X8R / Aftermarket", note: "CRITICAL: Fixes rattling and prevents engine ingestion." }, { category: "Oil Filter Housing Gasket", brand: "Elring", note: "Cures the most common major oil leak on the M43 block." }, { category: "Rear Coolant Flange", brand: "Genuine BMW", note: "Plastic connector at the back of the head. Replace proactively." }, { category: "Vacuum Hose Kit", brand: "Silicone Aftermarket", note: "Replace all old rotting rubber hoses to cure rough idling." }, { category: "Water Pump", brand: "Saleri / Hepu", note: "Replace proactively every 100k km to prevent overheating." }, { category: "Valve Cover Gasket", brand: "Elring", note: "Prone to leaking oil onto the exhaust manifold." }, { category: "Spark Plugs", brand: "NGK BKR6EK", note: "Dual-ground copper plugs; CNG may require specific gapping." } ] },
