    engineeringData: { blockDesign: "Cast Iron block with an aluminum cylinder head. The non-VANOS M50 is legendary for its massive, overbuilt construction. The cylinder head casting is significantly thicker than the later VANOS versions, making it highly resistant to cracking and immense boost pressures.", crankshaft: "Cast Iron, supported by 7 main bearings. Exceptionally smooth and perfectly balanced naturally due to the inline-6 layout.", pistonSpeed: "14.1 m/s @ 6000 RPM.", alternator: "80A or 105A Bosch/Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy.", wristPinDiameter: "22 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M9.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.68." }, cylinderHead: { combustionChamberVol: "Pent-roof combustion chamber.", intakePortFlow: "24-valve DOHC design. The non-VANOS head flows exceptionally well at high RPMs and features highly desirable, heavy-duty dual valve springs from the factory, allowing for safe 7,000+ RPM operation.", valveSizes: "Intake: 33.0 mm / Exhaust: 30.5 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Aggressive fixed duration. Lacking VANOS, the cams are ground for high-RPM power at the massive expense of low-end torque.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Non-VANOS architecture. The intake and exhaust camshaft timing is completely fixed, resulting in a distinct, peaky power delivery that requires high revs to access." }, oilAndCooling: { oilSquirters: "No dedicated under-piston cooling jets.", oilPumpType: "Rotor-type pump driven by a dedicated chain off the crankshaft.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "None (Air cooled oil pan)." }, fuelSystem: { systemType: "Bosch Motronic 3.1.", maxPressure: "3.0 Bar (Fuel Rail).", injectors: "6x Bosch EV1 Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "450+ Nm (With forced induction).", maxSafePowerStock: "400+ hp (The non-VANOS block and rods are incredibly strong, but require a turbocharger to reach these numbers).", maxSafeRPM: "7000+ RPM (Thanks to dual valve springs).", weakestLink: "Plastic Cooling Components, 2.0L Displacement limit, Lack of low-end torque." }, electrical: { coils: "Individual Coil Pack system (Coil-on-Plug).", ecu: "Bosch Motronic M3.1." } },
    recommendedParts: { description: "Crucial maintenance parts to bulletproof the legendary non-VANOS M50 engine.", parts: [ { category: "Water Pump (Metal Impeller)", brand: "Saleri / Stewart", note: "CRITICAL: Replaces the fragile factory plastic impeller." }, { category: "Aluminum Thermostat Housing", brand: "Meyle", note: "CRITICAL: Replaces the explosive plastic factory housing." }, { category: "Valve Cover Gasket Set", brand: "Elring", note: "Includes spark plug tube seals. Cures oil flooding into coils." }, { category: "Intake Rubber Boot", brand: "Genuine BMW", note: "Replace if cracked to cure unmetered vacuum leaks and rough idle." }, { category: "Idle Control Valve Hose", brand: "Genuine BMW", note: "Hidden under the manifold, frequently splits and causes stalling." }, { category: "Ignition Coil Pack", brand: "Bosch", note: "Replace individually if cracked or misfiring under load." }, { category: "Radiator", brand: "Behr", note: "Proactively replace if the plastic end tanks show white stress marks." }, { category: "Spark Plugs", brand: "NGK", note: "Dual-ground copper plugs; replace every 30k km." } ] },
    maintenanceSchedule: {
      fluidsAndDrivetrain: [ { interval: "40,000 km", timeLimit: "4 years", task: "Manual Gearbox Oil", details: "Drain and refill the Getrag manual gearbox.", parts: ["1.2L 75W-80 GL-4"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "40 EUR" }, { interval: "40,000 km", timeLimit: "4 years", task: "Rear Differential Oil", details: "Extract and refill the rear differential.", parts: ["1.7L 75W-90 GL-5"], importance: "High", laborDifficulty: "Easy", estimatedCost: "45 EUR" }, { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Flush DOT 4 fluid.", parts: ["1.0L DOT 4"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Automatic Transmission Fluid", details: "Drain and refill the ZF 5HP18 fluid and replace the filter.", parts: ["Dexron III ATF", "Filter"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "150 EUR" } ],
      oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 10W-40 or 15W-40. Keep the oil clean to protect the hydraulic lifters.", parts: ["5.75L 10W-40", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "65 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "40,000 km", timeLimit: "4 years", task: "Fuel Filter", details: "Replace the inline metal fuel filter to protect the aging injectors.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "25 EUR" } ],
      ignitionAndEngine: [ { interval: "60,000 km", timeLimit: "Unlimited", task: "Valve Cover Gasket Replacement", details: "Replace the rubber gasket and the inner spark plug tube seals to prevent the coils from shorting out in a pool of oil.", parts: ["VCG Kit"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "45 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Vacuum System Overhaul", details: "Remove the intake manifold and replace all rubber vacuum hoses, specifically the ICV hoses and the main intake boot.", parts: ["Vacuum Hoses", "Intake Gaskets"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "80 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Spark Plugs", details: "Replace standard dual-ground copper spark plugs.", parts: ["6x NGK Plugs"], importance: "High", laborDifficulty: "Easy", estimatedCost: "45 EUR" } ],
      preventiveAndSuspension: [ { interval: "100,000 km", timeLimit: "10 years", task: "Control Arm Bushings", details: "Replace the front thrust arm bushings to cure the infamous E-Series 80 km/h steering shimmy.", parts: ["Lemförder Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Serpentine Belt & Tensioner", details: "Replace the main accessory drive belt and inspect the tensioner pulleys for bearing noise.", parts: ["Belt Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "60 EUR" } ],
      coolingAndHvac: [ { interval: "40,000 km", timeLimit: "3 years", task: "Coolant Flush", details: "CRITICAL: Drain and refill the cooling system. Old coolant corrodes the aluminum cylinder head and degrades the plastic cooling parts.", parts: ["10.5L LC-87 Coolant"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Water Pump & Thermostat Housing", details: "CRITICAL: Proactively replace the water pump with a metal impeller unit and swap the plastic thermostat housing to aluminum.", parts: ["Water Pump", "Alu Housing"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "Viscous Fan Clutch", details: "Test the mechanical fan clutch. If it freewheels when hot, the car will overheat in traffic.", parts: ["Sachs Fan Clutch"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" } ],
      engineMechanical: [ { interval: "100,000 km", timeLimit: "Unlimited", task: "Idle Control Valve Cleaning", details: "Remove the ICV from under the manifold and soak it in carb cleaner to restore a smooth idle.", parts: ["Carb Cleaner"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "10 EUR" } ]
    },
