      { system: "Engine Coolant", capacity: "12.0 Liters", spec: "BMW LC-87 Coolant" },
      { system: "Manual Transmission", capacity: "1.25 Liters", spec: "75W-80 GL-4" },
      { system: "Automatic Transmission", capacity: "3.0 Liters", spec: "Dexron III ATF" },
      { system: "Rear Differential", capacity: "1.9 Liters", spec: "75W-90 GL-5 Synthetic" },
      { system: "Power Steering", capacity: "1.2 Liters", spec: "Dexron II ATF" },
      { system: "Brake Fluid", capacity: "1.0 Liter", spec: "DOT 4" },
      { system: "Windshield Washer", capacity: "4.0 Liters", spec: "Standard Anti-Freeze" },
      { system: "A/C Refrigerant", capacity: "1550g", spec: "R12" },
      { system: "Fuel Tank", capacity: "80 Liters", spec: "95 RON Unleaded" }
