    engineeringData: { blockDesign: "Cast Iron block with an aluminum cylinder head. The M51 is a massive evolutionary step over the M21. It replaces the fatal timing belt with a robust dual-row timing chain. The engine block itself is incredibly durable and heavily over-engineered.", crankshaft: "Forged Steel, supported by 7 main bearings. Exceptionally strong and perfectly balanced.", pistonSpeed: "14.1 m/s @ 4800 RPM.", alternator: "95A or 140A Bosch (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy.", wristPinDiameter: "26 mm.", connectingRodLength: "130 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.57." }, cylinderHead: { combustionChamberVol: "Pre-combustion chamber design.", intakePortFlow: "12-valve SOHC design. The incredibly long aluminum casting is highly sensitive to thermal shock and will warp if overheated.", valveSizes: "Intake: 36.0 mm / Exhaust: 31.0 mm.", valveStemDiameter: "7.0 mm.", camshaftDuration: "Mild diesel duration. Driven by the robust timing chain.", lifterType: "Hydraulic bucket tappets (Huge upgrade over the M21, eliminating manual valve adjustments).", specialFeature: "Swirl-chamber indirect injection." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Rotor-type pump driven by a dedicated chain.", thermostatOpening: "80°C Mechanical thermostat.", oilCooler: "Features an external air-to-oil cooler for severe duty." }, fuelSystem: { systemType: "Bosch VP37 Electronic Distributor Pump.", maxPressure: "150 Bar (At injectors).", injectors: "6x Mechanical Pintle Injectors (Cylinder 4 has an electronic needle lift sensor)." }, tuningLimits: { maxSafeTorqueStock: "350 Nm (With EPROM tune).", maxSafePowerStock: "180 hp (Requires EGT monitoring; pushing further risks the cylinder head).", maxSafeRPM: "4800 RPM", weakestLink: "Bosch VP37 Pump (Leaks/Wear), Timing Chain Stretch (Hot Starts), Plastic Water Pump." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE 2.1." } },
    recommendedParts: { description: "Crucial maintenance parts to prevent the catastrophic failure of the M51 diesel engine.", parts: [ { category: "VP37 Pump Seal Kit", brand: "Bosch", note: "CRITICAL: Mandatory to stop massive diesel leaks destroying coolant hoses." }, { category: "Hot Start Fix Relay", brand: "Aftermarket", note: "CRITICAL: Cures the endless warm cranking issue permanently." }, { category: "Water Pump (Metal Impeller)", brand: "Saleri", note: "CRITICAL: Replaces the fragile factory plastic impeller." }, { category: "Viscous Fan Clutch", brand: "Sachs", note: "CRITICAL: Replace to prevent catastrophic overheating in traffic." }, { category: "Glow Plugs", brand: "Bosch / Beru", note: "Replace all 6 proactively for reliable cold starts." }, { category: "Fuel Filter", brand: "Mann-Filter", note: "Change frequently to protect the expensive VP37 injection pump." }, { category: "Injector Return Lines", brand: "Gates", note: "Replace braided rubber lines to cure fuel system air leaks." }, { category: "Dual Mass Flywheel", brand: "LUK", note: "Replace if experiencing violent clunking on clutch engagement." } ] },
