      { system: "Windshield Washer", capacity: "5.0 Liters", spec: "Standard Anti-Freeze" },
      { system: "A/C Refrigerant", capacity: "1225g", spec: "R134a" },
      { system: "Fuel Tank", capacity: "70 Liters", spec: "95 RON Unleaded" }
