    engineeringData: { blockDesign: "Cast Iron block with a 16-valve aluminum cylinder head. The M47 is incredibly robust and heavily over-engineered. Crucially, the early 136hp version in the E-Series DOES NOT feature the fatal plastic swirl flaps in the intake manifold, making it mechanically bulletproof.", crankshaft: "Forged Steel, supported by 5 main bearings. Exceptionally strong and perfectly balanced for a 4-cylinder diesel.", pistonSpeed: "15.0 m/s @ 4000 RPM.", alternator: "150A Bosch/Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "16-valve DOHC design. The aluminum casting is excellent, completely curing the cracking issues of the older M21 generation.", valveSizes: "Intake: 26.0 mm / Exhaust: 26.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Mild diesel duration. Driven by a robust single-row timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Bosch VP44 Direct Injection. Replaced the archaic indirect injection, drastically improving fuel economy and torque output." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Rotor-type pump driven by a dedicated chain.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Features an external air-to-oil cooler." }, fuelSystem: { systemType: "Bosch VP44 Electronic Radial Piston Distributor Pump.", maxPressure: "1500+ Bar (Internal to pump).", injectors: "4x Mechanical Injectors (Cylinder 4 has a needle lift sensor)." }, tuningLimits: { maxSafeTorqueStock: "350 Nm (With EPROM tune).", maxSafePowerStock: "175 hp (Limited strictly by the maximum flow capacity of the VP44 injection pump).", maxSafeRPM: "4500 RPM", weakestLink: "Bosch VP44 Pump Electronics, Vibration Damper, Vacuum Lines, Dual Mass Flywheel." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE 3.0." } },
    recommendedParts: { description: "Crucial maintenance parts to bulletproof the famously quirky VP44 injection and vacuum systems of the M47 engine.", parts: [ { category: "VP44 Pump Rebuild Service", brand: "Bosch Specialist", note: "CRITICAL: The PSG5 transistor will inevitably burn out and strand the car." }, { category: "Vibration Damper (Crank Pulley)", brand: "Corteco", note: "CRITICAL: Replaces the tearing rubber pulley. ONLY use Corteco." }, { category: "Silicone Vacuum Hose Kit", brand: "Aftermarket", note: "CRITICAL: Replaces rotting factory lines to restore VNT turbo boost." }, { category: "Mass Air Flow Sensor", brand: "Bosch", note: "Replace proactively if power feels sluggish or flat." }, { category: "Glow Plugs", brand: "Bosch / Beru", note: "Replace all 4 proactively for reliable cold winter starts." }, { category: "Engine Mounts", brand: "Lemförder", note: "Fluid-filled mounts; replace to cure massive cabin vibrations." }, { category: "Dual Mass Flywheel", brand: "LUK", note: "Replace if experiencing violent clunking on clutch engagement." }, { category: "Fuel Filter", brand: "Mann-Filter", note: "Change frequently to protect the hyper-expensive VP44 pump." } ] },
