      ignitionAndEngine: [ { interval: "150,000 km", timeLimit: "Unlimited", task: "Vibration Damper Replacement", details: "CRITICAL: Proactively replace the heavy main crankshaft pulley. The rubber core tears and will eventually destroy the serpentine belt system.", parts: ["Corteco Damper", "Bolts"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "Vacuum System Overhaul", details: "CRITICAL: Replace all rubber vacuum hoses controlling the turbo and EGR with high-quality silicone to cure mysterious boost loss and limp mode issues.", parts: ["Silicone Hoses"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "30 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Glow Plug Replacement", details: "Replace all 4 glow plugs. Essential for cold weather starting.", parts: ["4x Bosch Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "Engine Mount Replacement", details: "Replace the heavy-duty fluid-filled mounts to stop the 4-cylinder diesel vibrations from shaking the entire cabin.", parts: ["2x Lemförder Mounts"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" } ],
