      { part: "Engine Oil Drain Plug", value: "33 Nm", note: "Always use a new copper crush washer." },
      { part: "Glow Plugs", value: "20 Nm", note: "CRITICAL: Thread carefully into the warm aluminum head with anti-seize to prevent snapping." },
      { part: "Wheel Bolts", value: "120 Nm", note: "Apply in a crisscross pattern." },
      { part: "Valve Cover Bolts", value: "10 Nm", note: "Tighten evenly; overtightening will crack the cover." },
      { part: "Cylinder Head Bolts", value: "80 Nm + wait 15 min + 90° + run engine 25 min + 90°", note: "CRITICAL: Extremely complex, multi-stage sequence." },
      { part: "Injection Pump Mounting Nuts", value: "22 Nm", note: "CRITICAL: Must be precisely set with a dial indicator to adjust static timing." },
      { part: "Water Pump Bolts", value: "22 Nm", note: "Tighten in a star pattern." },
      { part: "Differential Drain Plug", value: "60 Nm", note: "Always loosen the fill plug before removing the drain plug." },
      { part: "Transmission Fill/Drain", value: "40 Nm", note: "Ensure vehicle is level when checking fluid." },
      { part: "Injector Fuel Lines", value: "25 Nm", note: "Do not overtighten or the flared steel ends will crack." }
