    engineeringData: { blockDesign: "Cast Iron block with an aluminum cylinder head. The M51 replaces the fatal timing belt of older models with a robust dual-row timing chain. The engine block itself is incredibly durable and heavily over-engineered.", crankshaft: "Forged Steel, supported by 7 main bearings. Exceptionally strong and perfectly balanced.", pistonSpeed: "14.1 m/s @ 4800 RPM.", alternator: "95A or 140A Bosch (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy.", wristPinDiameter: "26 mm.", connectingRodLength: "130 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.57." }, cylinderHead: { combustionChamberVol: "Pre-combustion chamber design.", intakePortFlow: "12-valve SOHC design. The incredibly long aluminum casting is highly sensitive to thermal shock and will warp if overheated.", valveSizes: "Intake: 36.0 mm / Exhaust: 31.0 mm.", valveStemDiameter: "7.0 mm.", camshaftDuration: "Mild diesel duration. Driven by the robust timing chain.", lifterType: "Hydraulic bucket tappets (Huge upgrade over the M21, eliminating manual valve adjustments).", specialFeature: "Swirl-chamber indirect injection." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Rotor-type pump driven by a dedicated chain.", thermostatOpening: "80°C Mechanical thermostat.", oilCooler: "Features an external air-to-oil cooler for severe duty." }, fuelSystem: { systemType: "Bosch VP37 Electronic Distributor Pump.", maxPressure: "150 Bar (At injectors).", injectors: "6x Mechanical Pintle Injectors (Cylinder 4 has an electronic needle lift sensor)." }, tuningLimits: { maxSafeTorqueStock: "350 Nm (With EPROM tune).", maxSafePowerStock: "180 hp (Requires EGT monitoring; pushing further risks the cylinder head).", maxSafeRPM: "4800 RPM", weakestLink: "Bosch VP37 Pump (Leaks/Wear), Timing Chain Stretch (Hot Starts), Plastic Water Pump." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE 2.1." } },
    recommendedParts: { description: "Crucial maintenance parts to prevent the catastrophic failure of the M51 diesel engine.", parts: [ { category: "VP37 Pump Seal Kit", brand: "Bosch", note: "CRITICAL: Mandatory to stop massive diesel leaks destroying coolant hoses." }, { category: "Hot Start Fix Relay", brand: "Aftermarket", note: "CRITICAL: Cures the endless warm cranking issue permanently." }, { category: "Water Pump (Metal Impeller)", brand: "Saleri", note: "CRITICAL: Replaces the fragile factory plastic impeller." }, { category: "Viscous Fan Clutch", brand: "Sachs", note: "CRITICAL: Replace to prevent catastrophic overheating in traffic." }, { category: "Glow Plugs", brand: "Bosch / Beru", note: "Replace all 6 proactively for reliable cold starts." }, { category: "Fuel Filter", brand: "Mann-Filter", note: "Change frequently to protect the expensive VP37 injection pump." }, { category: "Injector Return Lines", brand: "Gates", note: "Replace braided rubber lines to cure fuel system air leaks." }, { category: "Dual Mass Flywheel", brand: "LUK", note: "Replace if experiencing violent clunking on clutch engagement." } ] },
    maintenanceSchedule: {
      fluidsAndDrivetrain: [ { interval: "40,000 km", timeLimit: "4 years", task: "Manual Gearbox Oil", details: "Drain and refill the ZF manual gearbox.", parts: ["1.25L 75W-80 GL-4"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "40 EUR" }, { interval: "40,000 km", timeLimit: "4 years", task: "Rear Differential Oil", details: "Extract and refill the rear differential.", parts: ["1.7L 75W-90 GL-5"], importance: "High", laborDifficulty: "Easy", estimatedCost: "45 EUR" }, { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Flush DOT 4 fluid.", parts: ["1.0L DOT 4"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Automatic Transmission Fluid", details: "Drain and refill the ZF 5HP18 fluid and replace the filter.", parts: ["Dexron III ATF", "Filter"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "150 EUR" } ],
      oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 10W-40 or 15W-40. Frequent oil changes protect the timing chain and hydraulic lifters from diesel soot.", parts: ["6.75L 15W-40", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "70 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Diesel Fuel Filter", details: "CRITICAL: Replace the inline metal fuel filter to protect the incredibly sensitive Bosch VP37 pump.", parts: ["Fuel Filter"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "25 EUR" } ],
      ignitionAndEngine: [ { interval: "Immediately", timeLimit: "Unlimited", task: "VP37 Pump Reseal & Timing Adjustment", details: "CRITICAL: The injection pump will inevitably leak diesel. It must be removed, resealed by a specialist, and perfectly timed to cure hot start issues.", parts: ["Seal Kit", "Labor"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "450 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Water Pump & Thermostat", details: "CRITICAL: Proactively replace the water pump with a metal impeller unit to prevent catastrophic overheating of the long aluminum head.", parts: ["Water Pump", "Thermostat"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Glow Plug Replacement", details: "Replace all 6 glow plugs. Essential for cold weather starting.", parts: ["6x Bosch Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "90 EUR" }, { interval: "40,000 km", timeLimit: "4 years", task: "Fuel Return Lines", details: "Replace the braided rubber fuel return lines between the injectors to prevent air from entering the fuel system causing stalling.", parts: ["Braided Hose"], importance: "High", laborDifficulty: "Easy", estimatedCost: "15 EUR" } ],
      preventiveAndSuspension: [ { interval: "100,000 km", timeLimit: "10 years", task: "Control Arm Bushings", details: "Replace the front thrust arm bushings to cure the infamous E-Series 80 km/h steering shimmy.", parts: ["Lemförder Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "Dual Mass Flywheel Replacement", details: "Replace the heavy DMF when doing a clutch job to prevent massive drivetrain vibrations.", parts: ["LUK DMF", "Clutch"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "800 EUR" } ],
      coolingAndHvac: [ { interval: "40,000 km", timeLimit: "3 years", task: "Coolant Flush", details: "CRITICAL: Drain and refill the cooling system. Old coolant corrodes the delicate aluminum cylinder head.", parts: ["10.5L LC-87 Coolant"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Viscous Fan Clutch", details: "Test the mechanical fan clutch. If it freewheels when hot, the car will overheat rapidly in traffic.", parts: ["Sachs Fan Clutch"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" } ],
      engineMechanical: [ { interval: "250,000 km", timeLimit: "Unlimited", task: "Timing Chain Inspection", details: "The massive M51 timing chain stretches over huge mileage. This heavily retards injection timing. Re-timing the pump can compensate, but eventually, the chains must be replaced.", parts: ["Timing Chain Kit"], importance: "Medium", laborDifficulty: "Expert", estimatedCost: "800 EUR" } ]
    },
