    sisterModels: [ { name: "BMW 525d (E39)", note: "The Fleet Edition is exactly the same hardware as the standard 163hp 525d, simply artificially restricted by the ECU software." } ],
    tuningPotential: [
      { stage: "Stage 1 (Un-Restriction Chip Tune)", power: "190 - 200 hp", notes: "THE ULTIMATE BARGAIN. Because the Fleet Edition is mechanically identical to the standard 163hp model, a software flash not only removes the 136hp restriction but can instantly tune it to a completely safe 195hp and 420Nm. You get Stage 1 power on an engine that has been babied by its software for its entire life.", zeroToHundred: "8.1s", hundredToTwoHundred: "N/A" },
      { stage: "Stage 2 (EGR Delete & Decat)", power: "205 - 215 hp", notes: "Requires mapping out the EGR valve, installing a straight-through decat downpipe to lower EGTs, and an aggressive tune. The massive cast-iron block handles this power effortlessly.", zeroToHundred: "7.7s", hundredToTwoHundred: "N/A" },
      { stage: "Stage 3 (Upgraded Turbo & CP3 Pump)", power: "250 - 280+ hp", notes: "Requires retrofitting the larger CP3 high-pressure fuel pump from the 3.0L model, upgrading the turbocharger, and installing a massive intercooler.", zeroToHundred: "6.5s", hundredToTwoHundred: "N/A" }
    ],
