      fluidsAndDrivetrain: [ { interval: "40,000 km", timeLimit: "4 years", task: "Manual Gearbox Oil", details: "Drain and refill the ZF manual gearbox.", parts: ["1.5L 75W-80 GL-4"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "45 EUR" }, { interval: "40,000 km", timeLimit: "4 years", task: "Rear Differential Oil", details: "Extract and refill the rear differential.", parts: ["1.0L 75W-90 GL-5"], importance: "High", laborDifficulty: "Easy", estimatedCost: "45 EUR" }, { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Flush DOT 4 fluid.", parts: ["1.0L DOT 4"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" }, { interval: "40,000 km", timeLimit: "4 years", task: "Automatic Transmission Fluid", details: "CRITICAL: The GM 5L40-E automatic is incredibly fragile. You MUST change the fluid and filter frequently to prevent the torque converter from disintegrating.", parts: ["Dexron VI ATF", "Filter Kit"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "180 EUR" } ],
      oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 5W-30 or 5W-40 Synthetic. Frequent oil changes protect the timing chain and turbo bearings from heavy diesel soot.", parts: ["6.5L 5W-40", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "75 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Diesel Fuel Filter", details: "CRITICAL: Replace the inline metal fuel filter to protect the incredibly sensitive and expensive Bosch common rail injectors.", parts: ["Fuel Filter"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "35 EUR" } ],
      ignitionAndEngine: [ { interval: "Immediately", timeLimit: "Unlimited", task: "Swirl Flap Delete (Automatic Models)", details: "CRITICAL: The plastic swirl flaps in the intake manifold WILL break and destroy the engine. Remove the manifold and install blanking plates.", parts: ["Blanking Plates", "Intake Gaskets"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" }, { interval: "Immediately", timeLimit: "Unlimited", task: "CCV Vortex Upgrade", details: "CRITICAL: Remove the valve cover breather and throw away the foam toilet-roll filter. Install the plastic Vortex separator from the E60 generation to prevent turbo failure.", parts: ["Vortex CCV Kit"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "Vacuum System Overhaul", details: "CRITICAL: Replace all rubber vacuum hoses controlling the turbo and engine mounts with high-quality silicone to cure mysterious boost loss and limp mode issues.", parts: ["Silicone Hoses"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "30 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Thermostat Replacement (Both)", details: "Replace BOTH the main engine thermostat and the EGR thermostat. They fail open, causing the engine to run cold and massively increasing fuel consumption.", parts: ["Main T-Stat", "EGR T-Stat"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "90 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Glow Plugs & Relay", details: "Replace all 6 glow plugs and the glow plug control module. Essential for cold weather starting and smooth idling.", parts: ["6x Plugs", "Relay"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "180 EUR" } ],
      preventiveAndSuspension: [ { interval: "100,000 km", timeLimit: "10 years", task: "Control Arm Bushings", details: "Replace the front thrust arm bushings to cure the infamous E-Series 80 km/h steering shimmy, worsened by the massive weight of the cast-iron block.", parts: ["Lemförder Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "110 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "Dual Mass Flywheel Replacement", details: "Replace the heavy DMF when doing a clutch job to prevent massive drivetrain vibrations.", parts: ["LUK DMF", "Clutch"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "900 EUR" } ],
