    engineeringData: { blockDesign: "Aluminum block with cast-iron cylinder liners. The N46 is an incredibly complex 4-cylinder engine that prioritizes fuel economy over durability. It introduced severe cost-cutting measures in its timing chain components.", crankshaft: "Cast Iron, supported by 5 main bearings. Features balance shafts to counter 4-cylinder vibrations.", pistonSpeed: "15.0 m/s @ 6000 RPM.", alternator: "110A or 150A Valeo/Bosch (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy.", wristPinDiameter: "22 mm.", connectingRodLength: "143 mm.", rodBoltSize: "M9.", crankMainJournal: "56.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.59." }, cylinderHead: { combustionChamberVol: "Pent-roof combustion chamber.", intakePortFlow: "16-valve DOHC design. The head is phenomenally complex, housing Double VANOS and the Valvetronic assembly.", valveSizes: "Intake: 32.0 mm / Exhaust: 29.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Variable on BOTH Intake and Exhaust sides. Controlled dynamically by Double VANOS.", lifterType: "Hydraulic bucket tappets with intermediate levers.", specialFeature: "Valvetronic & Double VANOS. The engine uses a complex eccentric shaft and an electric motor to continuously vary intake valve lift, completely eliminating the traditional throttle butterfly for efficiency." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Rotor-type pump driven by a dedicated chain.", thermostatOpening: "105°C Electronically mapped thermostat (Runs incredibly hot to burn off emissions, severely degrading rubber seals).", oilCooler: "Features a heat exchanger mounted to the oil filter housing." }, fuelSystem: { systemType: "Bosch Motronic MEV9.2.", maxPressure: "3.5 Bar (Fuel Rail).", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "250 Nm", maxSafePowerStock: "180 hp (Tuning an N46 is a catastrophic waste of money).", maxSafeRPM: "6500 RPM (Governed by Bosch ECU).", weakestLink: "Timing Chain & Guides (Fatal), Valve Stem Seals (Massive Oil Burn), Valvetronic Motor, Vacuum Pump, PCV System." }, electrical: { coils: "Individual Coil Pack system (4x Coil-on-Plug).", ecu: "Bosch Motronic MEV9.2." } },
    recommendedParts: { description: "Crucial maintenance parts to prevent the catastrophic failure of the N46 engine.", parts: [ { category: "Timing Chain Kit", brand: "Febi Bilstein / INA", note: "CRITICAL: Replaces stretching chain and exploding plastic guides." }, { category: "Valve Stem Seal Kit", brand: "Elring / Victor Reinz", note: "CRITICAL: Fixes the massive oil burning and blue smoke." }, { category: "Valvetronic Motor", brand: "VDO / Continental", note: "CRITICAL: Restores power and cures limp mode. Requires adaptation." }, { category: "Vacuum Pump Seal Kit", brand: "Elring", note: "CRITICAL: Stops major oil leak onto the hot exhaust." }, { category: "Valve Cover Gasket Set", brand: "Elring", note: "Includes Valvetronic motor gasket. Cures oil flooding into coils." }, { category: "CCV Breather Kit", brand: "Febi Bilstein", note: "CRITICAL: Replaces the clogged separator and brittle plastic hoses." }, { category: "Ignition Coil Pack", brand: "Bosch / Delphi", note: "Replace individually if cracked or misfiring under load (requires 4)." }, { category: "Timing Chain Tensioner", brand: "Genuine BMW", note: "Replace proactively to keep the fragile chain tight on cold starts." } ] },
