      oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 5W-30 or 5W-40 Synthetic. The incredibly tight tolerances of the Valvetronic system and the fragile timing chain require pristine oil.", parts: ["4.25L 5W-30", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "65 EUR" }, { interval: "Weekly", timeLimit: "N/A", task: "Check Engine Oil Level", details: "CRITICAL: The N46 burns massive amounts of oil through failing valve stem seals. Check the dipstick constantly.", parts: ["1L Top-up Oil"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "10 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" } ],
