      oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 5W-30 or 5W-40 Synthetic. The massive V8 requires pristine oil to protect the complex Valvetronic hardware.", parts: ["8.0L 5W-40", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "90 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" } ],
      ignitionAndEngine: [ { interval: "100,000 km", timeLimit: "Unlimited", task: "Valve Stem Seal Replacement", details: "CRITICAL: When the engine begins smoking blue after idling, the valve stem seals must be replaced using specialized pneumatic tools.", parts: ["Valve Stem Seals", "Special Tools"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "1500+ EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "Timing Chain Guide Overhaul", details: "CRITICAL: A massive teardown of the front engine to replace the brittle plastic chain guides before they shatter and destroy the engine.", parts: ["Timing Guide Kit", "Special Tools"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "1800+ EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Coolant Transfer Pipe & Valley Pan", details: "CRITICAL: When coolant weeps from the timing cover hole, remove the intake manifold and install an expanding aftermarket coolant pipe.", parts: ["Collapsible Pipe", "Valley Pan"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "600 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Alternator Bracket Seal", details: "CRITICAL: Remove the alternator and its massive bracket to replace the figure-8 oil seal behind it, curing the massive oil leak.", parts: ["Bracket Seal"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "300 EUR" }, { interval: "60,000 km", timeLimit: "Unlimited", task: "Valve Cover Gaskets (Both Sides)", details: "Replace the rubber gaskets and the inner spark plug tube seals to prevent the 8 coils from shorting out in a pool of oil.", parts: ["2x VCG Kits"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "90 EUR" } ],
      preventiveAndSuspension: [ { interval: "100,000 km", timeLimit: "10 years", task: "Control Arm Bushings", details: "Replace the front thrust arm bushings to cure the infamous E-Series 80 km/h steering shimmy, highly exacerbated by the weight of the V8.", parts: ["Lemförder Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Serpentine Belt & Tensioner", details: "Replace the main accessory drive belt and inspect the tensioner pulleys for bearing noise.", parts: ["Belt Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "70 EUR" } ],
      coolingAndHvac: [ { interval: "40,000 km", timeLimit: "3 years", task: "Coolant Flush", details: "CRITICAL: Drain and refill the massive 11.5L cooling system. Old coolant corrodes the all-aluminum block.", parts: ["11.5L LC-87 Coolant"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "75 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Water Pump & Thermostat", details: "Proactively replace the massive water pump and the mapped 105C thermostat to prevent catastrophic overheating of the V8.", parts: ["Water Pump", "Thermostat"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" } ],
