      fluidsAndDrivetrain: [ { interval: "40,000 km", timeLimit: "4 years", task: "Manual Gearbox Oil", details: "Drain and refill the Getrag manual gearbox.", parts: ["1.2L MTF-LT-5"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "40 EUR" }, { interval: "40,000 km", timeLimit: "4 years", task: "Rear Differential Oil", details: "Extract and refill the rear differential.", parts: ["0.8L 75W-90 GL-5"], importance: "High", laborDifficulty: "Easy", estimatedCost: "35 EUR" }, { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Flush DOT 4 LV fluid.", parts: ["1.0L DOT 4 LV"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Automatic Transmission Fluid", details: "Drain and refill the ZF 8HP45 fluid and replace the integrated pan/filter. Essential for longevity.", parts: ["ZF Lifeguard 8", "Pan/Filter"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "300 EUR" } ],
      oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 5W-30 or 5W-40 Synthetic. The incredibly fragile timing chain relies entirely on pristine oil to survive. Never exceed 10k km.", parts: ["5.0L 5W-30", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "70 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "60,000 km", timeLimit: "6 years", task: "Fuel Filter", details: "Replace the inline fuel filter (located under the vehicle, not in the tank like older models).", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "40 EUR" } ],
      ignitionAndEngine: [ { interval: "100,000 km", timeLimit: "Unlimited", task: "Timing & Oil Pump Chain Overhaul", details: "CRITICAL: A massive teardown to replace the notoriously weak timing and oil pump chains with the updated post-2015 components before they snap and destroy the engine.", parts: ["Timing Kit", "Oil Pump Chain Kit", "Special Tools"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "1500+ EUR" }, { interval: "Immediately on failure", timeLimit: "Unlimited", task: "Direct Injector Replacement", details: "CRITICAL: When the engine misfires violently on cold start or smells like raw fuel, the injectors are leaking. You MUST replace them and code them to the ECU.", parts: ["4x Bosch Injectors"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "800+ EUR" }, { interval: "80,000 km", timeLimit: "Unlimited", task: "Intake Valve Walnut Blasting", details: "Remove the intake manifold and blast the intake valves with crushed walnut shells to clear the massive carbon sludge buildup.", parts: ["Intake Gaskets", "Labor"], importance: "High", laborDifficulty: "Expert", estimatedCost: "300 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Oil Filter Housing Gasket (OFHG)", details: "CRITICAL: Replace the rubber gasket behind the oil filter housing. If ignored, oil will soak the serpentine belt, causing it to snap and be ingested into the engine.", parts: ["OFHG Gasket", "Alu Bolts"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "40 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Spark Plugs", details: "Replace highly specific spark plugs. Direct injection and turbocharging foul these plugs incredibly fast.", parts: ["4x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" } ],
      preventiveAndSuspension: [ { interval: "100,000 km", timeLimit: "10 years", task: "Control Arm Bushings", details: "Replace the front thrust arm bushings to cure the infamous steering shimmy.", parts: ["Lemförder Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Serpentine Belt & Tensioner", details: "Replace the main accessory drive belt and inspect the tensioner pulleys. CRITICAL if the OFHG is leaking.", parts: ["Belt Kit"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "80 EUR" } ],
      coolingAndHvac: [ { interval: "40,000 km", timeLimit: "3 years", task: "Coolant Flush", details: "CRITICAL: Drain and refill the cooling system.", parts: ["7.0L LC-87 Coolant"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Electric Water Pump & Thermostat", details: "Proactively replace the electric water pump and the mapped 108C thermostat to avoid catastrophic overheating.", parts: ["Pierburg Pump", "Thermostat", "Alu Bolts"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "450 EUR" } ],
      engineMechanical: [ { interval: "As Needed", timeLimit: "Unlimited", task: "Valvetronic Motor Replacement", details: "If the engine loses power, idles roughly, or throws Valvetronic codes, the electric actuator motor on the valve cover must be replaced.", parts: ["VDO Motor", "Gasket"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "250 EUR" } ]
