      oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 5W-30 Synthetic. The incredibly tight tolerances of the Valvetronic system and the sensitive VANOS solenoids require pristine oil.", parts: ["6.5L 5W-30", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "75 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" } ],
      ignitionAndEngine: [ { interval: "80,000 km", timeLimit: "Unlimited", task: "DISA Valve Rebuild (Both)", details: "CRITICAL: Remove BOTH DISA valves from the intake manifold and upgrade the internal flaps to aluminum to prevent the retaining pins from dropping into the engine.", parts: ["2x DISA Kits"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "140 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Oil Filter Housing Gasket (OFHG)", details: "CRITICAL: Replace the rubber gasket behind the oil filter housing. If ignored, oil will soak the serpentine belt, causing it to snap and be ingested into the engine.", parts: ["OFHG Gasket", "Alu Bolts"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "40 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Valve Cover Replacement", details: "Replace the entire plastic valve cover, as the CCV valve is integrated into it and cannot be replaced separately. Cures massive oil leaks and vacuum whistling.", parts: ["Valve Cover Assy"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "350 EUR" }, { interval: "60,000 km", timeLimit: "Unlimited", task: "VANOS Solenoid Cleaning", details: "Remove the two solenoids from the front of the block and clean them thoroughly with brake cleaner to restore throttle response.", parts: ["O-Rings", "Brake Cleaner"], importance: "High", laborDifficulty: "Easy", estimatedCost: "15 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Spark Plugs", details: "Replace high-quality platinum spark plugs.", parts: ["6x NGK Plugs"], importance: "High", laborDifficulty: "Easy", estimatedCost: "70 EUR" } ],
      preventiveAndSuspension: [ { interval: "100,000 km", timeLimit: "10 years", task: "Control Arm Bushings", details: "Replace the front thrust arm bushings to cure the infamous F-Series steering shimmy.", parts: ["Lemförder Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Serpentine Belt & Tensioner", details: "Replace the main accessory drive belt and inspect the tensioner pulleys. CRITICAL if the OFHG is leaking.", parts: ["Belt Kit", "Alu Bolts"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "80 EUR" } ],
      coolingAndHvac: [ { interval: "100,000 km", timeLimit: "8 years", task: "Electric Water Pump & Thermostat", details: "CRITICAL PREVENTATIVE: Do not wait for the electric water pump to fail. Replace it and the thermostat proactively at 100k km to avoid being stranded with an overheated, warped engine.", parts: ["Pierburg Pump", "Thermostat", "Alu Bolts"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "450 EUR" }, { interval: "40,000 km", timeLimit: "3 years", task: "Coolant Flush", details: "CRITICAL: Drain and refill the cooling system.", parts: ["8.5L LC-87 Coolant"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" } ],
