    engineeringData: { blockDesign: "Aluminum block with cast-iron cylinder liners. The N57 is a monumental 3.0L inline-6 diesel. It shares the rear-mounted timing chain architecture with the N47, but the inherent smoothness and perfect primary balance of the inline-6 drastically reduces the fatal chain-snapping vibrations that plague the 4-cylinder models.", crankshaft: "Forged Steel, supported by 7 main bearings. Exceptionally strong and perfectly balanced.", pistonSpeed: "14.0 m/s @ 4500 RPM.", alternator: "180A Valeo/Bosch (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy with gallery cooling.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "24-valve DOHC design. The aluminum casting is excellent, completely eliminating thermal cracking.", valveSizes: "Intake: 25.9 mm / Exhaust: 25.9 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Mild diesel duration. Driven by the rear-mounted timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Bosch Common Rail Direct Injection. Fuel is stored at massive pressure in a common rail and injected electronically, drastically reducing noise and maximizing the massive 560Nm torque curve." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Rotor-type pump driven by a dedicated chain.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Features an external air-to-oil cooler." }, fuelSystem: { systemType: "Bosch CP4.2 Common Rail High-Pressure Pump.", maxPressure: "1800 Bar (Fuel Rail).", injectors: "6x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "700 Nm", maxSafePowerStock: "350 hp (Stock turbo runs out of efficiency).", maxSafeRPM: "4500 RPM", weakestLink: "Swirl Flaps (Fatal), DPF (Clogging), Vibration Damper, Timing Chain (at 250k+ km)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE 7.3." } },
    recommendedParts: { description: "Crucial maintenance parts to bulletproof the incredible 3.0L N57 diesel engine.", parts: [ { category: "Swirl Flap Blanking Plates", brand: "Aftermarket", note: "CRITICAL: Prevents catastrophic engine death." }, { category: "Vibration Damper (Crank Pulley)", brand: "Corteco", note: "CRITICAL: Replaces the tearing rubber pulley. ONLY use Corteco." }, { category: "CP4 Pump Protection Screen", brand: "Whitbread", note: "Catches shrapnel if the high-pressure fuel pump fails." }, { category: "EGR Valve", brand: "BorgWarner / Wahler", note: "Clean frequently; replace if sticking to prevent limp mode." }, { category: "Main Thermostat", brand: "Mahle / Behr", note: "Fails open, causing the engine to run cold and ruin the DPF." }, { category: "Glow Plugs & Relay", brand: "Bosch / Beru", note: "Replace all 6 proactively, along with the glow plug control module." }, { category: "Engine Mounts", brand: "Lemförder", note: "Vacuum-actuated fluid mounts; replace to cure cabin vibrations." }, { category: "Water Pump", brand: "Saleri / Hepu", note: "Replace proactively to ensure bulletproof cooling." } ] },
